package com.asmj.marketplace.services;

import com.asmj.marketplace.model.UserAccount;
import com.asmj.marketplace.repository.UserAccountRepository;
import com.asmj.marketplace.service.CloudinaryImageService;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;
import org.springframework.security.core.Authentication;
import org.springframework.web.multipart.MultipartFile;

@Controller
public class ServiceMarketplaceController {
 private final ServiceCategoryRepository categories; private final ServiceProviderRepository providers;
 private final ServiceListingRepository listings; private final ServiceBookingRepository bookings;
 private final ServicePaymentRepository payments; private final ServiceCommissionRepository commissions;
 private final ServiceReviewRepository reviews; private final ServiceComplaintRepository complaints;
 private final ServicePlatformSettingsRepository settings; private final UserAccountRepository users;
 private final CloudinaryImageService cloudinary;
 public ServiceMarketplaceController(ServiceCategoryRepository categories, ServiceProviderRepository providers,
   ServiceListingRepository listings, ServiceBookingRepository bookings, ServicePaymentRepository payments,
   ServiceCommissionRepository commissions, ServiceReviewRepository reviews, ServiceComplaintRepository complaints,
   ServicePlatformSettingsRepository settings, UserAccountRepository users, CloudinaryImageService cloudinary) {
  this.categories=categories; this.providers=providers; this.listings=listings; this.bookings=bookings;
  this.payments=payments; this.commissions=commissions; this.reviews=reviews; this.complaints=complaints;
  this.settings=settings; this.users=users; this.cloudinary=cloudinary;
 }
 private String email(Authentication a){return a.getName();}
 private ServiceProvider ownProvider(Authentication a){return providers.findByEmailIgnoreCase(email(a)).orElse(null);}
 private boolean approved(ServiceProvider p){return p!=null && "APPROVED".equals(p.getStatus());}
 private ServiceBooking ownedBooking(String id, Authentication a){ServiceBooking b=bookings.findById(id).orElse(null); if(b==null) return null; ServiceProvider p=ownProvider(a); return b.getCustomerEmail().equalsIgnoreCase(email(a)) || (p!=null && p.getId().equals(b.getProviderId())) ? b : null;}

 @GetMapping("/services") public String browse(@RequestParam(required=false) String q,@RequestParam(required=false) String category,
   @RequestParam(required=false) String pin, Model model){
  List<ServiceListing> all;
  if(category!=null&&!category.isBlank()) all=listings.findByStatusAndActiveTrueAndCategoryIdOrderByCreatedAtDesc("APPROVED",category);
  else if(q!=null&&!q.isBlank()) all=listings.findByStatusAndActiveTrueAndTitleContainingIgnoreCaseOrderByCreatedAtDesc("APPROVED",q.trim());
  else all=listings.findByStatusAndActiveTrueOrderByCreatedAtDesc("APPROVED");
  all.removeIf(x -> !approved(providers.findById(x.getProviderId()).orElse(null)));
  if(pin!=null&&!pin.isBlank()) all.removeIf(x->x.getServicePinCodes()==null||!Arrays.stream(x.getServicePinCodes().split("[,\\s]+" )).anyMatch(pin.trim()::equals));
  model.addAttribute("services",all); model.addAttribute("categories",categories.findByActiveTrueOrderByNameAsc()); model.addAttribute("q",q); model.addAttribute("selectedCategory",category); model.addAttribute("pin",pin);
  return "services/catalog";
 }
 @GetMapping("/services/{id}") public String detail(@PathVariable String id,Model model){
  ServiceListing listing=listings.findById(id).orElse(null); if(listing==null||!listing.isActive()||!"APPROVED".equals(listing.getStatus())||!approved(providers.findById(listing.getProviderId()).orElse(null))) return "error";
  model.addAttribute("service",listing); model.addAttribute("reviews",reviews.findByListingIdOrderByCreatedAtDesc(id)); return "services/detail";
 }
 @GetMapping("/service-provider/register") public String providerRegister(Model model,Authentication auth){
  ServiceProvider p=ownProvider(auth); model.addAttribute("provider",p==null?new ServiceProvider():p); return "provider/services/register";
 }
 @PostMapping("/service-provider/register") public String saveProvider(@ModelAttribute ServiceProvider form,Authentication auth,RedirectAttributes ra){
  UserAccount user=users.findByEmailIgnoreCase(email(auth)).orElse(null); if(user==null){ra.addFlashAttribute("error","Account not found.");return "redirect:/service-provider/register";}
  ServiceProvider p=ownProvider(auth); if(p==null)p=new ServiceProvider();
  p.setEmail(email(auth)); p.setProviderType(clean(form.getProviderType(),20)); p.setDisplayName(clean(form.getDisplayName(),100));
  p.setContactName(clean(form.getContactName(),100)); p.setMobile(clean(form.getMobile(),20)); p.setUpiId(clean(form.getUpiId(),100)); p.setBusinessAddress(clean(form.getBusinessAddress(),250));
  p.setCity(clean(form.getCity(),80)); p.setState(clean(form.getState(),80)); p.setPinCodes(clean(form.getPinCodes(),1000));
  p.setExperienceYears(form.getExperienceYears()==null?0:Math.max(0,Math.min(60,form.getExperienceYears())));
  p.setQualifications(clean(form.getQualifications(),500)); p.setRegistrationNumber(clean(form.getRegistrationNumber(),100));
  p.setStatus("PENDING"); p.setAdminNote(null);
  providers.save(p); ra.addFlashAttribute("success","Provider application submitted. Admin approval is required before publishing services."); return "redirect:/service-provider/register";
 }
 @GetMapping("/provider/services") public String providerDashboard(Authentication auth,Model model){ServiceProvider p=ownProvider(auth); model.addAttribute("provider",p); model.addAttribute("listings",p==null?List.of():listings.findByProviderIdOrderByCreatedAtDesc(p.getId())); model.addAttribute("bookings",p==null?List.of():bookings.findByProviderIdOrderByCreatedAtDesc(p.getId())); model.addAttribute("commissions",p==null?List.of():commissions.findByProviderIdOrderByCreatedAtDesc(p.getId())); model.addAttribute("payments",p==null?List.of():payments.findByProviderIdOrderByCreatedAtDesc(p.getId())); return "provider/services/dashboard";}
 @GetMapping("/provider/services/new") public String newListing(Authentication auth,Model model,RedirectAttributes ra){ServiceProvider p=ownProvider(auth); if(!approved(p)){ra.addFlashAttribute("error","Your provider account must be approved before adding services.");return "redirect:/provider/services";} model.addAttribute("listing",new ServiceListing()); model.addAttribute("categories",categories.findByActiveTrueOrderByNameAsc()); return "provider/services/form";}
 @PostMapping("/provider/services") public String createListing(@ModelAttribute ServiceListing form,Authentication auth,RedirectAttributes ra){ServiceProvider p=ownProvider(auth); if(!approved(p)){ra.addFlashAttribute("error","Provider approval is required.");return "redirect:/provider/services";}
  if(blank(form.getTitle())||blank(form.getCategoryId())||blank(form.getDescription())){ra.addFlashAttribute("error","Title, category and description are required.");return "redirect:/provider/services/new";}
  ServiceCategory c=categories.findById(form.getCategoryId()).orElse(null); if(c==null||!c.isActive()){ra.addFlashAttribute("error","Select an active category.");return "redirect:/provider/services/new";}
  form.setId(null); form.setProviderId(p.getId());form.setProviderName(p.getDisplayName());form.setCategoryName(c.getName());form.setTitle(clean(form.getTitle(),120));form.setDescription(clean(form.getDescription(),2500));form.setPricingType(clean(form.getPricingType(),30));form.setServiceMode(clean(form.getServiceMode(),30));form.setServicePinCodes(clean(form.getServicePinCodes(),1000));Set<String> allowedPins=new HashSet<>(Arrays.asList(Optional.ofNullable(p.getPinCodes()).orElse("").split("[,\\s]+")));List<String> requestedPins=Arrays.stream(Optional.ofNullable(form.getServicePinCodes()).orElse("").split("[,\\s]+")).filter(x->!x.isBlank()).distinct().toList();if(!"ONLINE".equalsIgnoreCase(form.getServiceMode())&&(requestedPins.isEmpty()||!allowedPins.containsAll(requestedPins))){ra.addFlashAttribute("error","Service PIN codes must be selected from the PIN codes in your approved provider profile.");return "redirect:/provider/services/new";}
  form.setPrice(form.getPrice()==null?BigDecimal.ZERO:form.getPrice().max(BigDecimal.ZERO));form.setDurationMinutes(form.getDurationMinutes()==null?60:Math.max(15,Math.min(1440,form.getDurationMinutes())));form.setAvailableDays(clean(form.getAvailableDays(),100));form.setStartTime(clean(form.getStartTime(),5));form.setEndTime(clean(form.getEndTime(),5));form.setSlotIntervalMinutes(form.getSlotIntervalMinutes()==null?form.getDurationMinutes():Math.max(15,Math.min(480,form.getSlotIntervalMinutes())));form.setStatus("PENDING");form.setActive(true);listings.save(form);ra.addFlashAttribute("success","Service submitted for mandatory admin approval.");return "redirect:/provider/services"; }

 @GetMapping("/services/{id}/book") public String bookingForm(@PathVariable String id,Authentication auth,Model model){ServiceListing s=listings.findById(id).orElse(null);if(s==null||!"APPROVED".equals(s.getStatus()))return "error";model.addAttribute("service",s);model.addAttribute("booking",new ServiceBooking());return "services/book";}
 @PostMapping("/services/{id}/book") public String book(@PathVariable String id,@RequestParam String appointmentDateTime,@RequestParam String pinCode,@RequestParam(required=false) String serviceAddress,@RequestParam(required=false) String customerNotes,Authentication auth,RedirectAttributes ra){
  ServiceListing s=listings.findById(id).orElse(null);if(s==null||!s.isActive()||!"APPROVED".equals(s.getStatus())||!approved(providers.findById(s.getProviderId()).orElse(null))){ra.addFlashAttribute("error","This service is not available.");return "redirect:/services";}
  UserAccount customer=users.findByEmailIgnoreCase(email(auth)).orElse(null);if(customer==null){ra.addFlashAttribute("error","Please sign in again.");return "redirect:/login";}
  boolean online="ONLINE".equalsIgnoreCase(s.getServiceMode());if(!online&&(blank(pinCode)||!Arrays.stream(Optional.ofNullable(s.getServicePinCodes()).orElse("").split("[,\\s]+")).anyMatch(pinCode.trim()::equals))){ra.addFlashAttribute("error","This provider does not list service coverage for the entered PIN code.");return "redirect:/services/"+id+"/book";}
  Instant start; try { start=LocalDateTime.parse(appointmentDateTime).atZone(ZoneId.of("Asia/Kolkata")).toInstant(); } catch(Exception ex){ra.addFlashAttribute("error","Select a valid appointment date and time.");return "redirect:/services/"+id+"/book";} int duration=s.getDurationMinutes()==null?60:s.getDurationMinutes();Instant end=start.plusSeconds(duration*60L);LocalDateTime localStart=LocalDateTime.ofInstant(start,ZoneId.of("Asia/Kolkata"));if(!isWithinAvailability(s,localStart)){ra.addFlashAttribute("error","The selected time is outside this provider service schedule. Choose a listed working day and time slot.");return "redirect:/services/"+id+"/book";}
  if(start.isBefore(Instant.now().plus(Duration.ofMinutes(30)))){ra.addFlashAttribute("error","Choose an appointment at least 30 minutes in the future.");return "redirect:/services/"+id+"/book";}
  if(hasOverdueCommission(s.getProviderId())){ra.addFlashAttribute("error","This provider is temporarily unable to receive new bookings because of overdue platform commission.");return "redirect:/services/"+id+"/book";}
  if(!bookings.findConflicts(s.getProviderId(),start,end).isEmpty()){ra.addFlashAttribute("error","This provider already has a booking request or appointment during that time. Please choose another slot.");return "redirect:/services/"+id+"/book";}
  ServiceBooking b=new ServiceBooking();b.setListingId(id);b.setProviderId(s.getProviderId());b.setProviderName(s.getProviderName());b.setProviderUpiId(ownProviderFor(s.getProviderId())==null?null:ownProviderFor(s.getProviderId()).getUpiId());b.setCustomerEmail(email(auth));b.setCustomerName(customer.getFullName());b.setCustomerMobile(customer.getMobile());b.setServiceTitle(s.getTitle());b.setServiceAddress(clean(serviceAddress,300));b.setPinCode(clean(pinCode,10));b.setAppointmentStart(start);b.setAppointmentEnd(end);b.setAppointmentDisplay(LocalDateTime.ofInstant(start,ZoneId.of("Asia/Kolkata")).toString().replace("T"," "));b.setCustomerNotes(clean(customerNotes,1500));b.setQuotedAmount(s.getPrice());b.setStatus("PENDING");bookings.save(b);ra.addFlashAttribute("success","Booking request sent. It will be confirmed only after the provider accepts it.");return "redirect:/customer/service-bookings";
 }
 @GetMapping("/customer/service-bookings") public String customerBookings(Authentication auth,Model model){model.addAttribute("bookings",bookings.findByCustomerEmailOrderByCreatedAtDesc(email(auth)));return "services/customer-bookings";}
 @PostMapping("/provider/services/bookings/{id}/decision") public String bookingDecision(@PathVariable String id,@RequestParam String decision,@RequestParam(required=false) BigDecimal amount,@RequestParam(required=false) String note,Authentication auth,RedirectAttributes ra){ServiceProvider p=ownProvider(auth);ServiceBooking b=bookings.findById(id).orElse(null);if(!approved(p)||b==null||!p.getId().equals(b.getProviderId()))return "error";
  if("ACCEPT".equals(decision)){if((b.getQuotedAmount()==null||b.getQuotedAmount().compareTo(BigDecimal.ZERO)==0)&&(amount==null||amount.compareTo(BigDecimal.ZERO)<=0)){ra.addFlashAttribute("error","Enter the agreed quotation amount before accepting this booking.");return "redirect:/provider/services";}if(!bookings.findConflicts(p.getId(),b.getAppointmentStart(),b.getAppointmentEnd()).stream().filter(x->!x.getId().equals(b.getId())).toList().isEmpty()){ra.addFlashAttribute("error","Another booking now conflicts with this slot.");return "redirect:/provider/services";}b.setStatus("ACCEPTED");b.setAcceptedAt(Instant.now());if(amount!=null&&amount.compareTo(BigDecimal.ZERO)>=0)b.setAgreedAmount(amount);}
  else if("REJECT".equals(decision)){b.setStatus("REJECTED");}else return "error";b.setProviderResponse(clean(note,500));bookings.save(b);ra.addFlashAttribute("success","Booking updated.");return "redirect:/provider/services"; }
 @PostMapping("/provider/services/bookings/{id}/start") public String startService(@PathVariable String id,Authentication auth,RedirectAttributes ra){ServiceProvider p=ownProvider(auth);ServiceBooking b=bookings.findById(id).orElse(null);if(b==null||!approved(p)||!p.getId().equals(b.getProviderId())||!"ACCEPTED".equals(b.getStatus()))return "error";b.setStatus("IN_PROGRESS");bookings.save(b);ra.addFlashAttribute("success","Service marked as started.");return "redirect:/provider/services";}
 @PostMapping("/provider/services/bookings/{id}/complete") public String completeService(@PathVariable String id,Authentication auth,RedirectAttributes ra){ServiceProvider p=ownProvider(auth);ServiceBooking b=bookings.findById(id).orElse(null);if(b==null||!approved(p)||!p.getId().equals(b.getProviderId())||!"IN_PROGRESS".equals(b.getStatus()))return "error";b.setStatus("AWAITING_CUSTOMER_CONFIRMATION");b.setCompletedAt(Instant.now());bookings.save(b);ra.addFlashAttribute("success","Completion submitted for customer confirmation.");return "redirect:/provider/services";}
 @PostMapping("/customer/service-bookings/{id}/confirm") public String confirmCompletion(@PathVariable String id,Authentication auth,RedirectAttributes ra){ServiceBooking b=ownedBooking(id,auth);if(b==null||!b.getCustomerEmail().equalsIgnoreCase(email(auth))||!"AWAITING_CUSTOMER_CONFIRMATION".equals(b.getStatus()))return "error";b.setStatus("COMPLETED");b.setCustomerConfirmedAt(Instant.now());bookings.save(b);createCommission(b);ra.addFlashAttribute("success","Service completion confirmed. Please record your payment with the provider.");return "redirect:/customer/service-bookings";}
 @PostMapping("/customer/service-bookings/{id}/cancel") public String cancelBooking(@PathVariable String id,Authentication auth,RedirectAttributes ra){ServiceBooking b=ownedBooking(id,auth);if(b==null||!b.getCustomerEmail().equalsIgnoreCase(email(auth))||!("PENDING".equals(b.getStatus())||"ACCEPTED".equals(b.getStatus()))){ra.addFlashAttribute("error","This booking can no longer be cancelled online.");return "redirect:/customer/service-bookings";}b.setStatus("CANCELLED");bookings.save(b);ra.addFlashAttribute("success","Booking cancelled. Any direct payment/refund arrangement must be handled with the provider.");return "redirect:/customer/service-bookings";}
 private ServiceProvider ownProviderFor(String providerId){return providers.findById(providerId).orElse(null);}
 private boolean isWithinAvailability(ServiceListing s,LocalDateTime when){try{if(blank(s.getAvailableDays())||blank(s.getStartTime())||blank(s.getEndTime()))return false;String day=when.getDayOfWeek().name();boolean dayAllowed=Arrays.stream(s.getAvailableDays().split("[,\\s]+")).anyMatch(x->x.equalsIgnoreCase(day)||x.equalsIgnoreCase(day.substring(0,3)));LocalTime start=LocalTime.parse(s.getStartTime()),end=LocalTime.parse(s.getEndTime()),chosen=when.toLocalTime();int interval=s.getSlotIntervalMinutes()==null?s.getDurationMinutes():s.getSlotIntervalMinutes();long minutes=Duration.between(start,chosen).toMinutes();return dayAllowed&&!chosen.isBefore(start)&&!chosen.plusMinutes(s.getDurationMinutes()).isAfter(end)&&minutes>=0&&minutes%interval==0;}catch(Exception ex){return false;}}
 private boolean hasOverdueCommission(String providerId){LocalDate today=LocalDate.now(ZoneId.of("Asia/Kolkata"));return commissions.findByProviderIdAndStatus(providerId,"DUE").stream().anyMatch(c->c.getPeriodEnd()!=null&&c.getPeriodEnd().isBefore(today));}
 private void createCommission(ServiceBooking b){if(commissions.findByBookingId(b.getId()).isPresent())return;BigDecimal gross=b.getAgreedAmount()!=null?b.getAgreedAmount():b.getQuotedAmount();if(gross==null||gross.compareTo(BigDecimal.ZERO)<=0)return;ServicePlatformSettings st=settings.findById("default").orElseGet(ServicePlatformSettings::new);BigDecimal rate=st.getCommissionRate()==null?new BigDecimal("5.00"):st.getCommissionRate();LocalDate today=b.getCompletedAt()==null?LocalDate.now(ZoneId.of("Asia/Kolkata")):LocalDate.ofInstant(b.getCompletedAt(),ZoneId.of("Asia/Kolkata"));LocalDate monday=today.with(java.time.DayOfWeek.MONDAY);ServiceCommission c=new ServiceCommission();c.setBookingId(b.getId());c.setProviderId(b.getProviderId());c.setGrossAmount(gross);c.setCommissionRate(rate);c.setCommissionAmount(gross.multiply(rate).divide(new BigDecimal("100"),2,java.math.RoundingMode.HALF_UP));c.setPeriodStart(monday);c.setPeriodEnd(monday.plusDays(6));c.setStatus("DUE");commissions.save(c);}
 @PostMapping("/customer/service-bookings/{id}/payment") public String customerPayment(@PathVariable String id,@RequestParam BigDecimal amount,@RequestParam String method,@RequestParam(required=false) String utr,@RequestParam(required=false) MultipartFile proof,Authentication auth,RedirectAttributes ra){ServiceBooking b=ownedBooking(id,auth);if(b==null||!b.getCustomerEmail().equalsIgnoreCase(email(auth))||!"COMPLETED".equals(b.getStatus())||amount==null||amount.compareTo(BigDecimal.ZERO)<=0||!List.of("UPI","CASH").contains(method==null?"":method.toUpperCase(Locale.ROOT)))return "error";if("UPI".equalsIgnoreCase(method)&&blank(utr)&&(proof==null||proof.isEmpty())){ra.addFlashAttribute("error","For UPI payments, provide a UTR/reference or payment screenshot.");return "redirect:/customer/service-bookings";}try{ServicePayment p=payments.findByBookingId(id).orElseGet(ServicePayment::new);if("VERIFIED_BY_PROVIDER".equals(p.getStatus())){ra.addFlashAttribute("error","Payment has already been verified by the provider.");return "redirect:/customer/service-bookings";}p.setBookingId(id);p.setProviderId(b.getProviderId());p.setCustomerEmail(email(auth));p.setAmount(amount.max(BigDecimal.ZERO));p.setMethod(clean(method,20));p.setUtr(clean(utr,100));if(proof!=null&&!proof.isEmpty())p.setProofUrl(String.valueOf(cloudinary.uploadDocument(proof,"asmj-marketplace/service-payments").get("secure_url")));p.setStatus("SUBMITTED_TO_PROVIDER");payments.save(p);ra.addFlashAttribute("success","Payment details submitted to the provider for verification.");}catch(Exception e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/customer/service-bookings";}
 @PostMapping("/provider/services/bookings/{id}/payment/verify") public String verifyPayment(@PathVariable String id,Authentication auth,RedirectAttributes ra){ServiceProvider p=ownProvider(auth);ServicePayment pay=payments.findByBookingId(id).orElse(null);if(!approved(p)||pay==null||!p.getId().equals(pay.getProviderId())||!"SUBMITTED_TO_PROVIDER".equals(pay.getStatus()))return "error";pay.setStatus("VERIFIED_BY_PROVIDER");pay.setVerifiedAt(Instant.now());payments.save(pay);ra.addFlashAttribute("success","Payment verified and recorded.");return "redirect:/provider/services";}
 @PostMapping("/customer/service-bookings/{id}/review") public String review(@PathVariable String id,@RequestParam Integer rating,@RequestParam String comment,Authentication auth,RedirectAttributes ra){ServiceBooking b=ownedBooking(id,auth);if(b==null||!b.getCustomerEmail().equalsIgnoreCase(email(auth))||!"COMPLETED".equals(b.getStatus())||reviews.existsByBookingId(id))return "error";ServiceReview r=new ServiceReview();r.setBookingId(id);r.setListingId(b.getListingId());r.setProviderId(b.getProviderId());r.setCustomerEmail(email(auth));r.setRating(Math.max(1,Math.min(5,rating)));r.setComment(clean(comment,1000));reviews.save(r);ra.addFlashAttribute("success","Thank you for your review.");return "redirect:/customer/service-bookings";}
 @PostMapping("/customer/service-bookings/{id}/complaint") public String complaint(@PathVariable String id,@RequestParam String subject,@RequestParam String description,Authentication auth,RedirectAttributes ra){ServiceBooking b=ownedBooking(id,auth);if(b==null||!b.getCustomerEmail().equalsIgnoreCase(email(auth)))return "error";ServiceComplaint c=new ServiceComplaint();c.setBookingId(id);c.setRaisedBy(email(auth));c.setSubject(clean(subject,120));c.setDescription(clean(description,2000));c.setStatus("OPEN");complaints.save(c);ra.addFlashAttribute("success","Your complaint was submitted to admin.");return "redirect:/customer/service-bookings";}

 @GetMapping("/admin/services") public String adminServices(Model model){model.addAttribute("categories",categories.findAll());model.addAttribute("providers",providers.findAll());model.addAttribute("listings",listings.findAll());model.addAttribute("commissions",commissions.findByStatusOrderByCreatedAtDesc("DUE"));model.addAttribute("complaints",complaints.findAllByOrderByCreatedAtDesc());model.addAttribute("settings",settings.findById("default").orElseGet(ServicePlatformSettings::new));return "admin/services/index";}
 @PostMapping("/admin/services/categories") public String category(@RequestParam String name,@RequestParam(required=false) String description,@RequestParam(required=false) String parentId,RedirectAttributes ra){ServiceCategory c=new ServiceCategory();c.setName(clean(name,80));c.setDescription(clean(description,300));c.setParentId(blank(parentId)?null:parentId);c.setActive(true);categories.save(c);ra.addFlashAttribute("success","Service category saved.");return "redirect:/admin/services";}
 @PostMapping("/admin/services/providers/{id}/status") public String providerStatus(@PathVariable String id,@RequestParam String status,@RequestParam(required=false) String note,RedirectAttributes ra){ServiceProvider p=providers.findById(id).orElse(null);if(p==null)return "error";if(!List.of("APPROVED","REJECTED","SUSPENDED").contains(status))return "error";p.setStatus(status);p.setAdminNote(clean(note,500));if("APPROVED".equals(status))p.setApprovedAt(Instant.now());providers.save(p);ra.addFlashAttribute("success","Provider status updated.");return "redirect:/admin/services";}
 @PostMapping("/admin/services/listings/{id}/status") public String listingStatus(@PathVariable String id,@RequestParam String status,RedirectAttributes ra){ServiceListing s=listings.findById(id).orElse(null);if(s==null)return "error";if(!List.of("APPROVED","REJECTED","SUSPENDED").contains(status))return "error";s.setStatus(status);if("APPROVED".equals(status))s.setApprovedAt(Instant.now());listings.save(s);ra.addFlashAttribute("success","Listing moderation updated.");return "redirect:/admin/services";}
 @PostMapping("/admin/services/settings") public String saveSettings(@RequestParam BigDecimal commissionRate,RedirectAttributes ra){if(commissionRate.compareTo(BigDecimal.ZERO)<0||commissionRate.compareTo(new BigDecimal("50"))>0){ra.addFlashAttribute("error","Commission must be between 0 and 50 percent.");return "redirect:/admin/services";}ServicePlatformSettings s=settings.findById("default").orElseGet(ServicePlatformSettings::new);s.setCommissionRate(commissionRate);settings.save(s);ra.addFlashAttribute("success","Service commission setting saved.");return "redirect:/admin/services";}
 @PostMapping("/admin/services/commissions/{id}/paid") public String markCommissionPaid(@PathVariable String id,RedirectAttributes ra){ServiceCommission c=commissions.findById(id).orElse(null);if(c==null)return "error";c.setStatus("PAID");c.setPaidAt(Instant.now());commissions.save(c);ra.addFlashAttribute("success","Commission marked as received from provider.");return "redirect:/admin/services";}
 @PostMapping("/admin/services/complaints/{id}/resolve") public String resolveComplaint(@PathVariable String id,@RequestParam String note,RedirectAttributes ra){ServiceComplaint c=complaints.findById(id).orElse(null);if(c==null)return "error";c.setStatus("RESOLVED");c.setAdminNote(clean(note,1000));c.setResolvedAt(Instant.now());complaints.save(c);ra.addFlashAttribute("success","Complaint marked resolved.");return "redirect:/admin/services";}
 private String clean(String v,int max){if(v==null)return null;String s=v.trim();return s.length()>max?s.substring(0,max):s;} private boolean blank(String v){return v==null||v.trim().isEmpty();}
}
